/* ==========================================
   A. 变量（底层基础配置）
   ========================================== */
.chat-app {
  --dress-list-sheet-radius: 0;
  --dress-list-row-pad-y: 12px;      /* ☂️ 消息列表行高 */
  --dress-list-row-pad-x: 16px;      /* ☂️ 消息列表左右内边距 */
  --dress-list-preview-size: 13px;   /* ☂️ 预览文字大小 */
  --dress-list-name-size: 16px;      /* ☂️ 名字文字大小 */
  --dress-list-unread-bg: var(--ink);
  --dress-list-unread-fg: #fff;
}
html[data-theme="dark"] .chat-app {
  --dress-list-unread-bg: #f0f0f0;
  --dress-list-unread-fg: #1a1a1a;
}

/* ==========================================
   B. 顶栏整体（高度与上下位置）
   ========================================== */
.chat-app .chat-inbox {
  /* ☂️ 顶栏的顶部留白，数字越大，顶栏往下走 */
  padding-top: 0px !important; 
}
.chat-app .chat-inbox-top {
  /* ☂️ 顶栏高度，0代表不占用上下空间，只靠里面的元素撑开 */
  height: 0px !important; 
  padding: 0 12px !important;
  display: flex !important;
  align-items: center !important; 
  position: relative !important;
  box-sizing: border-box !important;
  overflow: visible !important;

  /* ☂️ 整个顶栏往上提，负数越大越靠上（例如 -4px，改成 -10px 会整体更往上） */
  margin-top: -4px !important; 
}

/* ==========================================
   C. 标题“微信”
   ========================================== */
.chat-app .chat-inbox-title {
  position: absolute !important;
  left: 50% !important;         /* ☂️ 左右居中，改小往左，改大往右 */

  /* ☂️ 标题上下位置，改大往下走（如改成 calc(50% - 5px) 就是往下5px） */
  top: calc(50% - 10px) !important; 

  transform: translate(-50%, -50%) !important;
  margin: 0 !important;
  font-size: 0 !important;      
  pointer-events: none !important;
}
.chat-app .chat-inbox-title::after {
  content: "微信" !important;
  font-size: 17px !important;   /* ☂️ 标题字号 */
  font-weight: 600 !important;
  display: inline-block !important;
}

/* ==========================================
   D. 左侧返回按钮（透明但可点击）
   ========================================== */
.chat-app button.chat-back {
  opacity: 0 !important;        
  visibility: visible !important;
  pointer-events: auto !important; 
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: transparent !important;
  fill: transparent !important;
  stroke: transparent !important;
  /* ☂️ 返回按钮的上下位置，正数往下，负数往上 */
  margin-top: 5px !important;
}
.chat-app button.chat-back *,
.chat-app button.chat-back svg,
.chat-app button.chat-back i,
.chat-app button.chat-back img {
  display: none !important;
  opacity: 0 !important;
}

/* ==========================================
   E. 单聊 / 群聊 切换按钮
   ========================================== */
.chat-app .chat-inbox-filter {
  order: 1 !important;
  margin-left: auto !important; 
  margin-right: 33px !important;    /* ☂️ 右侧距离，改大往左移 */
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;             /* ☂️ 单聊和群聊两个按钮之间的间距 */
  position: relative !important;

  top: -11px !important;            /* ☂️ 整体上下位置，负数往上，正数往下 */
  left: -8px !important;            /* ☂️ 整体左右位置，负数往左，正数往右 */
}
.chat-app .chat-inbox-filter button:first-child {
  opacity: 0 !important;        
  visibility: visible !important;
  pointer-events: auto !important; 
  width: 24px !important;       
  height: 24px !important;
  background-image: none !important; 
}
.chat-app .chat-inbox-filter button:nth-child(2):not([class*="add"]):not([class*="plus"]) {
  display: flex !important;     
  width: 21px !important;           /* ☂️ 群聊图标大小 */
  height: 21px !important;
  padding: 0 !important;
  border: 0 !important;
  box-shadow: none !important;
  font-size: 0 !important;
  /* ☂️ 群聊图标链接 */
  background-image: url('https://nos.netease.com/vcloud-statistic/nrtc/ca1cca89-3f24-41a2-8efe-cc4e607b1626.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  position: static !important;
  margin: 0 !important;
  /* ☂️ 群聊图标上下位置。translateY 第一个值是往下，负数往上 */
  transform: translateY(2px) !important;
}
.chat-app .chat-inbox-filter button::before,
.chat-app .chat-inbox-filter button::after,
.chat-app .chat-inbox-filter button svg,
.chat-app .chat-inbox-filter button img,
.chat-app .chat-inbox-filter button i,
.chat-app .chat-inbox-filter button span {
  display: none !important;
}
@media (prefers-color-scheme: light) {
  .chat-app .chat-inbox-filter button:nth-child(2):not([class*="add"]):not([class*="plus"]) {
    filter: invert(0.3) brightness(1.0) !important; /* ☂️ 日间群聊图标颜色 */
  }
}
@media (prefers-color-scheme: dark) {
  .chat-app .chat-inbox-filter button:nth-child(2):not([class*="add"]):not([class*="plus"]) {
    filter: invert(0.6) brightness(1.2) !important; /* ☂️ 夜间群聊图标颜色 */
  }
}

/* ==========================================
   F. 右上角加号（尺寸与位置）
   ========================================== */
.chat-app button.chat-head-icon {
  order: 99 !important; 
  position: static !important; 
  align-self: center !important; 

  width: 21px !important;           /* ☂️ 加号图标大小 */
  height: 21px !important;

  border: 0 !important;
  padding: 0 !important;
  box-shadow: none !important;
  font-size: 0 !important;
  color: transparent !important;
  text-indent: -9999px !important; 
  background-color: transparent !important; 

  background-image: url('https://nos.netease.com/vcloud-statistic/nrtc/b665b2da-7e6e-46c9-8322-d6bcd0b2eb97.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;

  margin-top: 0 !important; 
  margin-left: 0 !important; 

  /* ☂️ 加号位置。
     第一个数值 -8px 控制左右（负数往左，正数往右）；
     第二个数值 7px 控制上下（正数往下，负数往上）。 */
  transform: translate(-8px, 7px) !important; 
}

@media (prefers-color-scheme: light) {
  .chat-app button.chat-head-icon {
    filter: invert(0.3) brightness(1.0) !important; /* ☂️ 日间加号颜色 */
  }
}
@media (prefers-color-scheme: dark) {
  .chat-app button.chat-head-icon {
    filter: invert(0.6) brightness(1.2) !important; /* ☂️ 夜间加号颜色 */
  }
}

.chat-app button.chat-head-icon > *,
.chat-app button.chat-head-icon::before,
.chat-app button.chat-head-icon::after,
.chat-app button.chat-head-icon svg,
.chat-app button.chat-head-icon i,
.chat-app button.chat-head-icon img,
.chat-app button.chat-head-icon span {
  display: none !important;
}

/* ==========================================
   G. 消息列表（扁平化风格）
   ========================================== */
.chat-app .chat-list-sheet,
.chat-app .chat-scroll {
  border-radius: 0 !important;
  box-shadow: none !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  width: 100% !important;
}

.chat-app .chat-row-wrap,
.chat-app .chat-row-slider,
.chat-app .chat-row {
  border-radius: 0 !important; 
  margin: 0 !important;        
  box-shadow: none !important; 
  width: 100% !important;      
  box-sizing: border-box !important;
}

.chat-app .chat-row {
  background: #ffffff !important;    /* ☂️ 日间消息列表背景色 */
  padding: 12px 16px !important;     /* ☂️ 消息列表内边距（上下 左右） */
  position: relative !important;
}
html[data-theme="dark"] .chat-app .chat-row {
  background: #191919 !important;    /* ☂️ 夜间消息列表背景色 */
}

.chat-app .chat-row-wrap.is-pinned .chat-row {
  background: #f7f7f7 !important;    /* ☂️ 日间置顶消息背景色 */
}
html[data-theme="dark"] .chat-app .chat-row-wrap.is-pinned .chat-row {
  background: #2a2a2a !important;    /* ☂️ 夜间置顶消息背景色 */
}

.chat-app .chat-row-wrap + .chat-row-wrap .chat-row::before {
  content: "" !important;
  position: absolute !important;
  left: 74px !important;             /* ☂️ 分割线起点（74px 约等于头像右侧位置） */
  right: 0 !important;     
  top: 0 !important;
  height: 1px !important;
  background: rgba(0, 0, 0, 0.005) !important; /* ☂️ 日间分割线颜色（透明度改小可以更淡） */
  transform: scaleY(0.05) !important;          /* ☂️ 分割线粗细（0.05 已经极细） */
  transform-origin: 0 0 !important; 
  pointer-events: none !important;
}
html[data-theme="dark"] .chat-app .chat-row-wrap + .chat-row-wrap .chat-row::before {
  background: rgba(255, 255, 255, 0.03) !important; /* ☂️ 夜间分割线颜色 */
}

.chat-app .chat-ava-list,
.chat-app .chat-ava-list *,
.chat-app .chat-ava-list img {
  border-radius: 6px !important;      /* ☂️ 头像圆角（数字越大越圆） */
  overflow: hidden !important;
}

.chat-app .chat-row-pin-mark {
  display: none !important; 
}

.chat-app .chat-row-unread {
  position: absolute !important;
  top: 7px !important;                /* ☂️ 红点上下位置，数字越大越靠下，越小越靠上 */
  left: 50px !important;              /* ☂️ 红点左右位置，数字越大越靠右，越小越靠左 */
  right: auto !important;
  z-index: 10 !important;    
  margin: 0 !important;
  background: #fa5151 !important;     /* ☂️ 红点颜色 */
  color: #fff !important;
  border-radius: 999px !important;
  min-width: 15px !important;         /* ☂️ 红点最小宽度 */
  height: 15px !important;            /* ☂️ 红点高度 */
  padding: 0 5px !important;
  font-weight: 600 !important;
  font-size: 11px !important;         /* ☂️ 红点文字大小 */
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  line-height: 1 !important;
  box-sizing: border-box !important;
  padding-top: 0 !important;          /* ☂️ 文字上内边距，数字越大文字越靠下 */
  padding-bottom: 1px !important;      /* ☂️ 文字下内边距，数字越大文字越靠上 */
}
.chat-app .chat-row-preview.has-unread {
  color: var(--ink) !important; 
  font-weight: 600 !important;
}
.chat-app .chat-row-wrap:has(.chat-row-unread) .chat-row {
  background: rgba(0,0,0,.03) !important;
}
html[data-theme="dark"] .chat-app .chat-row-wrap:has(.chat-row-unread) .chat-row {
  background: rgba(255,255,255,.04) !important;
}

/* ==========================================
   H. 底栏四个按钮
   ========================================== */
.chat-app .chat-tabdock {
  border-radius: 0 !important;
  box-shadow: none !important; 
  padding: 0 !important;
  width: 100% !important;
  left: 0 !important;
  right: 0 !important;
  background-color: #e6e6e6 !important;     /* ☂️ 日间底栏背景色 */
  border-top: 0.5px solid rgba(0,0,0,0.08) !important; /* ☂️ 日间底栏顶部线 */
}
html[data-theme="dark"] .chat-app .chat-tabdock {
  background-color: #1a1a1a !important;     /* ☂️ 夜间底栏背景色 */
  border-top: 0.5px solid rgba(255,255,255,0.08) !important; /* ☂️ 夜间底栏顶部线 */
}

.chat-app .chat-tabdock-pill {
  display: flex !important;
  flex-direction: row !important; 
  justify-content: space-around !important; 
  align-items: center !important;
  width: 100% !important;
  padding: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important; 
  background: transparent !important;
  box-sizing: border-box !important;
}

.chat-app .chat-tabdock-pill > *,
.chat-app .chat-tabdock-pill::before {
  flex: 1 !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  text-align: center !important;
  font-size: 10px !important;              /* ☂️ 底栏文字大小 */
  padding: 6px 0 !important;               /* ☂️ 底栏内部上下留白 */
  background: transparent !important;
  box-sizing: border-box !important;
  color: #8e8e93 !important;               /* ☂️ 底栏日间文字颜色 */
}
html[data-theme="dark"] .chat-app .chat-tabdock-pill > *,
html[data-theme="dark"] .chat-app .chat-tabdock-pill::before {
  color: #d0d0d0 !important;               /* ☂️ 底栏夜间文字颜色 */
}
.chat-app .chat-tabdock-pill > * > * {
  display: none !important;
}

/* 底栏按钮排列顺序 */
.chat-app .chat-tabdock-pill > *:nth-child(1) { order: 1 !important; }
.chat-app .chat-tabdock-pill::before { order: 2 !important; } 
.chat-app .chat-tabdock-pill > *:nth-child(2) { order: 3 !important; }
.chat-app .chat-tabdock-pill > *:nth-child(3) { order: 4 !important; }
.chat-app .chat-tabdock-pill > *:nth-child(4) { display: none !important; }

/* 1. 微信 */
.chat-app .chat-tabdock-pill > *:nth-child(1)::before {
  content: "" !important;
  background-image: url('https://nos.netease.com/vcloud-statistic/nrtc/0547f910-79ab-4428-b05e-939ee8a2f67f.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 24px !important;                  /* ☂️ 微信图标大小 */
  height: 24px !important;
  display: block !important;
  margin-bottom: 3px !important;           /* ☂️ 图标与文字的间距 */
}
.chat-app .chat-tabdock-pill > *:nth-child(1)::after {
  content: "微信" !important;
  line-height: 1 !important;
  display: block !important;
}
html[data-theme="dark"] .chat-app .chat-tabdock-pill > *:nth-child(1)::before {
  filter: invert(0.8) brightness(1.1) !important; 
}

/* 2. 通讯录（凭空生成） */
.chat-app .chat-tabdock-pill::before {
  content: "通讯录" !important;
  flex: 1 !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  line-height: 1 !important;
  background-image: url('https://nos.netease.com/vcloud-statistic/nrtc/cb2f6f46-ddcd-4b7d-90b9-d8f94447ae04.png') !important;
  background-size: 23px 23px !important;   /* ☂️ 通讯录图标大小 */
  background-repeat: no-repeat !important;
  background-position: center top -1px !important; /* ☂️ 通讯录图标上下位置 */
  padding-top: 27px !important;            /* ☂️ 为图标预留的高度（影响文字位置） */
  transform: translateY(4px) !important;   /* ☂️ 整体上下位置（负数往上，正数往下） */
  box-sizing: border-box !important;
  background-color: transparent !important;
  text-align: center !important;
  color: #8e8e93 !important; 
}
html[data-theme="dark"] .chat-app .chat-tabdock-pill::before {
  filter: invert(0.8) brightness(1.1) !important;
  color: #191919 !important; 
}

/* 3. 发现 */
.chat-app .chat-tabdock-pill > *:nth-child(2)::before {
  content: "" !important;
  background-image: url('https://nos.netease.com/vcloud-statistic/nrtc/ceaa4de3-a767-4456-90ec-c2363bcd3f24.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 24px !important;                  /* ☂️ 发现图标大小 */
  height: 24px !important;
  display: block !important;
  margin-bottom: 3px !important;           /* ☂️ 图标与文字的间距 */
}
.chat-app .chat-tabdock-pill > *:nth-child(2)::after {
  content: "发现" !important;
  line-height: 1 !important;
  display: block !important;
}
html[data-theme="dark"] .chat-app .chat-tabdock-pill > *:nth-child(2)::before {
  filter: invert(0.8) brightness(1.1) !important;
}

/* 4. 我 */
.chat-app .chat-tabdock-pill > *:nth-child(3)::before {
  content: "" !important;
  background-image: url('https://nos.netease.com/vcloud-statistic/nrtc/f0658d12-e477-46f4-85c9-1be3a204af2d.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 24px !important;                  /* ☂️ “我”图标大小 */
  height: 24px !important;
  display: block !important;
  margin-bottom: 3px !important;           /* ☂️ 图标与文字的间距 */
}
.chat-app .chat-tabdock-pill > *:nth-child(3)::after {
  content: "我" !important;
  line-height: 1 !important;
  display: block !important;
}
html[data-theme="dark"] .chat-app .chat-tabdock-pill > *:nth-child(3)::before {
  filter: invert(0.8) brightness(1.1) !important;
}

/* ==========================================
   底栏选中状态：图标和文字一起变绿
   ========================================== */
.chat-app .chat-tabdock-pill > *:active,
.chat-app .chat-tabdock-pill > *.active,
.chat-app .chat-tabdock-pill > *.on,
.chat-app .chat-tabdock-pill > *[class*="active"],
.chat-app .chat-tabdock-pill > *[class*="selected"],
.chat-app .chat-tabdock-pill > *:active::after,
.chat-app .chat-tabdock-pill > *.active::after,
.chat-app .chat-tabdock-pill > *.on::after,
.chat-app .chat-tabdock-pill > *[class*="active"]::after,
.chat-app .chat-tabdock-pill > *[class*="selected"]::after {
  color: #07c160 !important;                  /* ☂️ 底栏选中时的文字颜色（微信绿） */
}
.chat-app .chat-tabdock-pill > *:active::before,
.chat-app .chat-tabdock-pill > *.active::before,
.chat-app .chat-tabdock-pill > *.on::before,
.chat-app .chat-tabdock-pill > *[class*="active"]::before,
.chat-app .chat-tabdock-pill > *[class*="selected"]::before,
html[data-theme="dark"] .chat-app .chat-tabdock-pill > *:active::before,
html[data-theme="dark"] .chat-app .chat-tabdock-pill > *.active::before,
html[data-theme="dark"] .chat-app .chat-tabdock-pill > *.on::before,
html[data-theme="dark"] .chat-app .chat-tabdock-pill > *[class*="active"]::before,
html[data-theme="dark"] .chat-app .chat-tabdock-pill > *[class*="selected"]::before {
  filter: invert(66%) sepia(85%) saturate(2000%) hue-rotate(90deg) brightness(95%) contrast(90%) !important; /* ☂️ 底栏选中时的图标颜色（微信绿） */
}
